import { getAgentDisplayName, tryResolveAddMcpAgentId } from "../mcp/agents.js";
import "../init/agents.js";
import { detectPluginsAgents, getPluginsTargetName, isUserScopeOnlyPluginsTarget, mappedPluginsTargets, pluginsInstallableAgents } from "./targets.js";
import { collectYesAgents, noDetectedAgentsMessage } from "../init/plan.js";
import { agentChoicesFrom, pickAgentsInteractively, resolveAgentSelection } from "../utils/agent_picker.js";
import { detectAgent } from "../init/detect_host.js";
//#region src/plugins/plan.ts
const assertPluginsCanRun = (options) => {
	if (options.yes || options.interactive || options.hasAgents) return;
	throw new Error("No interactive terminal. Pass -y to install into detected agents, or --agent <name> to name them.");
};
async function resolvePluginsPlan(options) {
	assertPluginsCanRun({
		yes: options.yes,
		interactive: options.interactive,
		hasAgents: options.agents.length > 0
	});
	const prompt = options.interactive && !options.yes;
	const scope = options.global ? "global" : "project";
	const available = pluginsInstallableAgents(scope);
	const availableSet = new Set(available);
	const scoped = await detectPluginsAgents({
		scope,
		cwd: options.cwd,
		...options.detectInstalledAgents ? { detectInstalledAgents: options.detectInstalledAgents } : {}
	});
	const detected = options.yes && options.agents.length === 0 ? await collectYesAgents({
		detected: () => scoped,
		detectAgent: options.detectAgent ?? detectAgent,
		acceptHost: (id) => availableSet.has(id) || getPluginsTargetName(id) !== void 0
	}) : scoped;
	const selected = await resolveAgentSelection({
		specified: options.agents,
		choices: agentChoicesFrom(available, detected),
		detected,
		message: "Which coding agents should get the Neon plugin? (space to toggle, enter to confirm)",
		nonInteractiveMessage: noDetectedAgentsMessage({
			scope,
			supported: available,
			fix: options.yes ? "run-without-yes" : "pass-yes",
			nameAgent: true
		}),
		resolveSpecified: (raw) => {
			if (raw === "*") throw new Error("neon plugins does not accept --agent *. Pass --agent <name> for each coding agent, or omit --agent to use detected agents.");
			const id = tryResolveAddMcpAgentId(raw);
			if (!id) throw new Error(`Unknown agent: "${raw}". Supported agents: ${available.join(", ")}`);
			return id;
		},
		pick: prompt ? options.pickAgents ?? pickAgentsInteractively : void 0,
		interactive: prompt
	});
	const agents = [];
	const skipped = [];
	const userScopeSkipped = [];
	for (const id of selected) {
		const target = getPluginsTargetName(id);
		if (target === void 0) {
			skipped.push(id);
			continue;
		}
		if (scope === "project" && isUserScopeOnlyPluginsTarget(target)) {
			userScopeSkipped.push(id);
			continue;
		}
		agents.push(id);
	}
	if (agents.length === 0) {
		if (userScopeSkipped.length > 0 && skipped.length === 0) {
			const names = userScopeSkipped.map((id) => getAgentDisplayName(id)).join(", ");
			throw new Error(`${names}: plugins are user-level. Pass --global. Without --global: ${pluginsInstallableAgents("project").join(", ")}`);
		}
		throw new Error(`None of the selected agents can install plugins. Supported agents: ${available.join(", ")}`);
	}
	return {
		scope,
		agents,
		skipped,
		userScopeSkipped,
		targets: mappedPluginsTargets(agents, scope)
	};
}
//#endregion
export { assertPluginsCanRun, resolvePluginsPlan };
